const f = (v: number | null | undefined, digits = 1) =>
  v == null
    ? "Sin observación"
    : new Intl.NumberFormat("es-CO", { maximumFractionDigits: digits }).format(
        v,
      );
const pct = (v: number) => `${f(v * 100)} %`;
function Panel({
  children,
  className = "",
}: {
  children: ReactNode;
  className?: string;
}) {
  return <section className={"panel " + className}>{children}</section>;
}
function Tag({ children }: { children: ReactNode }) {
  return <span className="tag">{children}</span>;
}
function Metric({
  label,
  value,
  unit,
  icon,
}: {
  label: string;
  value: string;
  unit?: string;
  icon: ReactNode;
}) {
  return (
    <div className="metric">
      <div className="metric-top">
        {label}
        {icon}
      </div>
      <strong>
        {value}
        <small>{unit}</small>
      </strong>
    </div>
  );
}
function Flow() {
  return (
    <div className="flow">
      {[
        "Llegada",
        "Registro / Triage",
        "Cola priorizada",
        "Consulta médica",
        "Observación / Egreso",
      ].map((s, i) => (
        <div className="flow-step" key={s}>
          <span>0{i + 1}</span>
          <strong>{s}</strong>
          {i < 4 && <ChevronRight size={18} />}
        </div>
      ))}
    </div>
  );
}

